import fs from "node:fs";
import path from "node:path";
import {
  DATA_FILE,
  PAGES_LOADING_DATA,
  SITE_DIR,
  SPEAKER_IMAGE_DIR,
  STAGED_DIR,
} from "./config.js";

const PREFIX = "const PROGRAMME_DATA = ";

const HEADER = `// Programme data for the CBT Course Series: days, modules (title, venue,
// speakers) and speaker details. Generated by admin-tool/ — edit it there
// (npm start in admin-tool) rather than by hand. Must stay valid JSON after
// the "const PROGRAMME_DATA =" prefix so the admin tool can read it back.
`;

// programme-data.js is JSON behind a `const PROGRAMME_DATA =` prefix, so the
// site can load it with a plain <script> tag and this tool can parse it.
export function parseDataText(text) {
  const start = text.indexOf(PREFIX);
  if (start === -1) throw new Error(`programme-data.js doesn't contain "${PREFIX.trim()}"`);
  const json = text.slice(start + PREFIX.length).trim().replace(/;$/, "");
  const data = JSON.parse(json);
  if (!Array.isArray(data.days) || !Array.isArray(data.speakers)) {
    throw new Error("programme-data.js must have `days` and `speakers` arrays");
  }
  return data;
}

export function serializeData(data) {
  return `${HEADER}${PREFIX}${JSON.stringify(data, null, 2)};\n`;
}

export function readLocalData() {
  return parseDataText(fs.readFileSync(DATA_FILE, "utf8"));
}

export function versionStamp(date = new Date()) {
  const p = (n) => String(n).padStart(2, "0");
  return `${date.getFullYear()}${p(date.getMonth() + 1)}${p(date.getDate())}${p(date.getHours())}${p(date.getMinutes())}${p(date.getSeconds())}`;
}

export function bumpDataVersion(html, version) {
  return html.replace(/(js\/programme-data\.js\?v=)[^"']*/g, `$1${version}`);
}

// A speaker `image` is either "" , a site-relative path (optionally with a
// ?v= cache-buster), or "staged:<file>" for a photo not yet saved.
export function localImagePath(image) {
  if (!image || image.startsWith("staged:")) return null;
  return path.join(SITE_DIR, image.split("?")[0]);
}

// Writes programme-data.js (copying staged photos into
// assets/images/speakers/ first) and bumps the cache-buster in the pages
// that load it. Returns the saved data and the site-relative files written.
export function saveLocalData(nested) {
  const version = versionStamp();
  const data = structuredClone(nested);
  const written = [];

  fs.mkdirSync(SPEAKER_IMAGE_DIR, { recursive: true });
  data.speakers.forEach((s) => {
    if (!s.image || !s.image.startsWith("staged:")) return;
    const stagedFile = path.resolve(STAGED_DIR, s.image.slice("staged:".length));
    if (!stagedFile.startsWith(STAGED_DIR + path.sep)) throw new Error(`Invalid photo path for ${s.name}.`);
    if (!fs.existsSync(stagedFile)) throw new Error(`Staged photo for ${s.name} is missing (${stagedFile}). Add the photo again.`);
    const ext = path.extname(stagedFile).toLowerCase() || ".jpg";
    fs.readdirSync(SPEAKER_IMAGE_DIR)
      .filter((f) => path.parse(f).name === s.id)
      .forEach((f) => fs.rmSync(path.join(SPEAKER_IMAGE_DIR, f)));
    const rel = `assets/images/speakers/${s.id}${ext}`;
    fs.copyFileSync(stagedFile, path.join(SITE_DIR, rel));
    s.image = `${rel}?v=${version}`;
    written.push(rel);
  });

  fs.writeFileSync(DATA_FILE, serializeData(data));
  written.push("js/programme-data.js");

  PAGES_LOADING_DATA.forEach((page) => {
    const file = path.join(SITE_DIR, page);
    if (!fs.existsSync(file)) return;
    const html = fs.readFileSync(file, "utf8");
    const next = bumpDataVersion(html, version);
    if (next !== html) {
      fs.writeFileSync(file, next);
      written.push(page);
    }
  });

  return { data, version, written };
}
